const STORAGE_KEY = 'notepad-content';
const ON_BEFORE_UNLOAD = 'OnBeforeUnload';

let dotNetRef;
let beforeUnloadHandler;

export function initialize(dotNetObjRef) {
    dotNetRef = dotNetObjRef;
}

export function loadContent() {
    return localStorage.getItem(STORAGE_KEY);
}

export function saveContent(content) {
    localStorage.setItem(STORAGE_KEY, content);
}

export function clearContent() {
    localStorage.removeItem(STORAGE_KEY);
}

export function enableLeaveGuard() {
    if (beforeUnloadHandler) return;
    beforeUnloadHandler = (e) => {
        e.preventDefault();
    };
    window.addEventListener('beforeunload', beforeUnloadHandler);
}

export function disableLeaveGuard() {
    if (beforeUnloadHandler) {
        window.removeEventListener('beforeunload', beforeUnloadHandler);
        beforeUnloadHandler = null;
    }
}

export function dispose() {
    disableLeaveGuard();
    dotNetRef = null;
}

using Microsoft.JSInterop;

namespace sv_737b4aef36624923b1a1013c9a98d801.Components.Pages;

public sealed class NotepadInterop : IAsyncDisposable
{
    internal const string ModulePath = "./Components/Pages/Notepad.razor.js";
    internal const string InitMethod = "initialize";
    internal const string LoadMethod = "loadContent";
    internal const string SaveMethod = "saveContent";
    internal const string ClearMethod = "clearContent";
    internal const string EnableGuardMethod = "enableLeaveGuard";
    internal const string DisableGuardMethod = "disableLeaveGuard";
    internal const string DisposeMethod = "dispose";

    private readonly IJSRuntime _js;
    private IJSObjectReference? _module;

    public NotepadInterop(IJSRuntime js) => _js = js;

    private async ValueTask<IJSObjectReference> GetModuleAsync()
        => _module ??= await _js.InvokeAsync<IJSObjectReference>("import", ModulePath);

    public async ValueTask InitializeAsync(DotNetObjectReference<Notepad> dotNetRef)
    {
        var module = await GetModuleAsync();
        await module.InvokeVoidAsync(InitMethod, dotNetRef);
    }

    public async ValueTask<string?> LoadContentAsync()
    {
        var module = await GetModuleAsync();
        return await module.InvokeAsync<string?>(LoadMethod);
    }

    public async ValueTask SaveContentAsync(string content)
    {
        var module = await GetModuleAsync();
        await module.InvokeVoidAsync(SaveMethod, content);
    }

    public async ValueTask ClearContentAsync()
    {
        var module = await GetModuleAsync();
        await module.InvokeVoidAsync(ClearMethod);
    }

    public async ValueTask EnableLeaveGuardAsync()
    {
        var module = await GetModuleAsync();
        await module.InvokeVoidAsync(EnableGuardMethod);
    }

    public async ValueTask DisableLeaveGuardAsync()
    {
        var module = await GetModuleAsync();
        await module.InvokeVoidAsync(DisableGuardMethod);
    }

    public async ValueTask DisposeAsync()
    {
        try
        {
            if (_module is not null)
            {
                await _module.InvokeVoidAsync(DisposeMethod);
                await _module.DisposeAsync();
            }
        }
        catch (JSDisconnectedException) { }
    }
}

